interface StationView {                       // passive contract
    String query();
    void showTotal(double total);
}
final class StationPresenter {
    private final StationView view; private final StationModel model;
    StationPresenter(StationView v, StationModel m) { view = v; model = m; }
    void queryChanged() { view.showTotal(model.total(view.query())); }
}
// view: stationView.queryField.addActionListener(e -> presenter.queryChanged());

public final class StationController {
    @FXML private TextField queryField;
    @FXML private Label totalLabel;
    private final StationPresenter presenter;
    private final StringProperty total = new SimpleStringProperty();
    @FXML private void initialize() {
        totalLabel.textProperty().bind(total);
        queryField.textProperty().addListener((o, oldV, newV) -> total.set(
            presenter.totalFor(newV)));
    }
}

